WITH with_windows AS (SELECT *, SUM(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct, CUME_DIST() OVER (PARTITION BY channel ORDER BY discount_pct DESC) AS discount_pct_cume_dist, STDDEV_SAMP(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_stddev_samp_discount_pct FROM promotions) SELECT DATE_TRUNC('MONTH', ends_on) AS activity_month, CASE WHEN cumulative_discount_pct >= 1 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_discount_pct_tier, SUM(cumulative_discount_pct) AS total_cumulative_discount_pct, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list_2, COUNT(*) FILTER (WHERE promo_code = 'BUNDLE') AS bundle_rows, COUNT(*) FILTER (WHERE promo_code = 'VIP') AS vip_rows FROM with_windows GROUP BY 1, 2 HAVING total_cumulative_discount_pct > 0
